import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown';

  const invoiceNumber = invoice.number || 'DRAFT';

  let text = `${invoiceNumber}\n`;
  text += `${customerName}\n`;
  text += '\n';

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const vat = lineVAT(line);
    const qtyStr = String(line.qty).padStart(3, ' ');
    const nameStr = line.name.padEnd(35, ' ');
    const unitPriceStr = formatEuros(line.unitPrice).padStart(10, ' ');
    const totalStr = formatEuros(total).padStart(10, ' ');
    text += `${qtyStr}  ${nameStr}${unitPriceStr}  ${totalStr}\n`;

    // Show discount if present
    if (line.discountPercent && line.discountPercent > 0) {
      const discountStr = formatEuros(discount).padStart(10, ' ');
      text += `      ${line.discountPercent}% discount${' '.repeat(23)}${discountStr}\n`;
    }

    // Show VAT if present
    if (line.vatRate > 0) {
      const vatStr = formatEuros(vat).padStart(10, ' ');
      text += `      ${line.vatRate}% VAT${' '.repeat(28)}${vatStr}\n`;
    }
  }

  const totals = invoiceTotals(invoice);
  text += '\n';
  if (totals.discount > 0) {
    const discountStr = formatEuros(totals.discount).padStart(10, ' ');
    text += `Discount: ${discountStr}\n`;
  }
  if (totals.vat > 0) {
    const vatStr = formatEuros(totals.vat).padStart(10, ' ');
    text += `VAT:      ${vatStr}\n`;
  }
  text += `Total: ${formatEuros(totals.total)}`;

  return text;
}

