    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const issued = issueInvoice(r.value, []).value;
  // Total: 51425
  const paid = recordPayment(issued, { amount: 30000, date: '2024-01-20' }).value;
  const text = renderInvoiceText(paid);

  assert.ok(text.includes('Paid:'), 'Should show paid line');
  assert.ok(text.includes('€300.00'), 'Should show partial payment amount');
  // Make sure it shows the full total, not the remaining balance
  assert.ok(text.includes('Total: €514.25'), 'Should show full total');
});

