test('renderInvoiceText with discount and voucher together', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }]
  });

  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const text = renderInvoiceText(withVoucher.value);

  const lines = text.split('\n');
  const hasDiscount = lines.some((l) => l.startsWith('Discount:'));
  const hasVoucher = lines.some((l) => l.startsWith('Voucher:'));

  assert.equal(hasDiscount, true, 'Should show line discount');
  assert.equal(hasVoucher, true, 'Should show voucher');

  // Both should appear before total
  const discountIdx = lines.findIndex((l) => l.startsWith('Discount:'));
  const voucherIdx = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(discountIdx < totalIdx, 'Discount before total');
  assert.ok(voucherIdx < totalIdx, 'Voucher before total');
});

