test('renderInvoiceText calculates total after discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 }
