test('renderInvoiceText shows voucher before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const text = renderInvoiceText(withVoucher.value);

  // Should show voucher before total
  assert.ok(text.includes('Voucher:'), 'Should show voucher line');
  assert.ok(text.includes('€50.00'), 'Should show voucher amount');

  const lines = text.split('\n');
  const voucherIdx = lines.findIndex((l) => l.includes('Voucher:'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(voucherIdx >= 0, 'Voucher line exists');
  assert.ok(totalIdx >= 0, 'Total line exists');
  assert.ok(voucherIdx < totalIdx, 'Voucher appears before total');
});

